const FLASH={"bai1": [{"id": "b1c1", "img": "../hinh-anh/khtn/fc-bai1-nghien-cuu.webp", "svg": "", "f": "Nghiên cứu khoa học là gì?", "b": "Hoạt động tìm tòi, khám phá ra cái mới bằng quan sát, thí nghiệm có phương pháp."}, {"id": "b1c2", "img": "../hinh-anh/khtn/fc-bai1-vat-song.webp", "svg": "", "f": "Vật sống có những dấu hiệu nào?", "b": "Trao đổi chất, sinh trưởng, sinh sản và cảm ứng."}, {"id": "b1c3", "img": "../hinh-anh/khtn/fc-sua-vat-khong-song.webp", "svg": "", "f": "Than củi, hòn đá thuộc loại vật gì?", "b": "Vật không sống — không có các hoạt động sống."}, {"id": "b1c4", "img": "../hinh-anh/khtn/fc-bai1-linh-vuc.webp", "svg": "", "f": "KHTN gồm những lĩnh vực nào?", "b": "Vật lí học, Hóa học, Sinh học, Thiên văn học, Khoa học Trái Đất."}, {"id": "b1c5", "img": "../hinh-anh/khtn/fc-sua-nuoc-soi.webp", "svg": "", "f": "Hiện tượng nước sôi thuộc lĩnh vực nào?", "b": "Vật lí học (sự chuyển thể của chất)."}], "bai2": [{"id": "b2c1", "img": "../hinh-anh/khtn/fc-bai2-rua-tay.webp", "svg": "", "f": "Sau khi làm thí nghiệm xong phải làm gì?", "b": "Rửa sạch tay bằng xà phòng."}, {"id": "b2c2", "img": "../hinh-anh/khtn/fc-sua-nhiet-ke-vo.webp", "svg": "", "f": "Làm vỡ nhiệt kế thủy ngân thì xử lí thế nào?", "b": "Mở toang cửa sổ cho thoáng • ra ngoài một thời gian • đeo khẩu trang + găng tay • gom bằng bìa cứng (không dùng chổi) • báo giáo viên."}, {"id": "b2c3", "img": "../hinh-anh/khtn/fc-sua-hoa-chat-do.webp", "svg": "", "f": "Hóa chất đổ ra sàn thì làm gì?", "b": "Báo giáo viên và trải giấy thấm lên để ngăn hóa chất lan rộng."}, {"id": "b2c4", "img": "../hinh-anh/khtn/bai2-bieu-tuong-ghs.png", "svg": "", "f": "Kí hiệu trong hình cảnh báo điều gì?", "b": "Chất nguy hại cho sức khỏe (hệ thống GHS) — phải đọc kĩ nhãn trước khi dùng."}, {"id": "b2c5", "img": "", "svg": "b2c5x", "f": "Hai việc tuyệt đối cấm trong phòng thực hành?", "b": "Ăn uống trong phòng; nếm hay ngửi trực tiếp hóa chất."}], "bai3": [{"id": "b3c1", "img": "../hinh-anh/khtn/fc-bai3-kinh-lup-cau-tao.webp", "svg": "", "f": "Bộ phận chính của kính lúp là gì?", "b": "Một thấu kính lồi gắn trong khung có tay cầm."}, {"id": "b3c2", "img": "../hinh-anh/khtn/fc-bai3-quan-sat-la.webp", "svg": "", "f": "Số bội giác (3x, 5x…) cho biết điều gì?", "b": "Khả năng phóng to ảnh của vật của kính lúp."}, {"id": "b3c3", "img": "../hinh-anh/khtn/fc-sua-phong-to.webp", "svg": "", "f": "Kính lúp phóng to khoảng bao nhiêu lần?", "b": "Khoảng 3 đến 20 lần."}, {"id": "b3c4", "img": "../hinh-anh/khtn/fc-bai3-xem-tem.webp", "svg": "", "f": "Cách dùng kính lúp đúng?", "b": "Điều chỉnh khoảng cách giữa kính và vật đến khi nhìn ảnh rõ nét nhất."}, {"id": "b3c5", "img": "../hinh-anh/khtn/fc-sua-bao-quan-kinh-lup.webp", "svg": "", "f": "Bảo quản kính lúp thế nào?", "b": "Lau bằng khăn mềm, cất nơi khô ráo, tránh rơi vỡ/trầy xước."}], "bai4": [{"id": "b4c1", "img": "", "svg": "b4c1x", "f": "Kính hiển vi quang học phóng to khoảng bao nhiêu lần?", "b": "Khoảng 40 đến 3000 lần."}, {"id": "b4c2", "img": "", "svg": "b4c2x", "f": "Kính hiển vi gồm hai bộ phận thấu kính nào?", "b": "Vật kính và thị kính."}, {"id": "b4c3", "img": "", "svg": "b4c3x", "f": "Độ phóng đại của kính hiển vi tính thế nào?", "b": "Độ phóng đại vật kính × độ phóng đại thị kính."}, {"id": "b4c4", "img": "../hinh-anh/khtn/fc-bai4-quan-sat-mau.webp", "svg": "", "f": "Khi nào phải dùng kính hiển vi thay cho kính lúp?", "b": "Khi vật quá nhỏ (tế bào, vi khuẩn) — kính lúp chỉ phóng to 3–20 lần, không đủ."}, {"id": "b4c5", "img": "", "svg": "b4c5", "f": "Kể tên các bộ phận chính của kính hiển vi quang học.", "b": "Chân kính, ống kính, ốc điều chỉnh (ốc to, ốc nhỏ), bàn kính, đèn chiếu sáng, vật kính, thị kính."}], "bai5": [{"id": "b5c1", "img": "", "svg": "b5c1x", "f": "Đơn vị đo độ dài hợp pháp của nước ta?", "b": "Mét (m)."}, {"id": "b5c2", "img": "", "svg": "b5c2x", "f": "GHĐ của thước là gì?", "b": "Độ dài lớn nhất mà thước đo được."}, {"id": "b5c3", "img": "", "svg": "b5c3x", "f": "ĐCNN của thước là gì?", "b": "Khoảng cách giữa hai vạch chia liên tiếp trên thước."}, {"id": "b5c4", "img": "", "svg": "b5c4x", "f": "Thước có GHĐ 20 cm và ĐCNN 1 mm thì đo được vật dài nhất bao nhiêu?", "b": "20 cm — GHĐ là độ dài lớn nhất mà thước đo được; ĐCNN 1 mm là khoảng cách giữa hai vạch chia liên tiếp."}, {"id": "b5c5", "img": "../hinh-anh/khtn/fc-sua-mat-vuong-goc.webp", "svg": "", "f": "Khi đọc kết quả đo, đặt mắt thế nào?", "b": "Mắt nhìn vuông góc với vạch chia của thước."}, {"id": "b5c6", "img": "", "svg": "b5c6", "f": "1 mL bằng bao nhiêu cm³?", "b": "1 cm³ — đo thể tích vật rắn bằng bình chia độ: V = V₂ − V₁."}], "bai6": [{"id": "b6c1", "img": "", "svg": "b6c1x", "f": "Số 380 g ghi trên hộp sữa cho biết điều gì?", "b": "Khối lượng của sữa trong hộp (khối lượng tịnh)."}, {"id": "b6c2", "img": "", "svg": "b6c2x", "f": "0,2 tạ bằng bao nhiêu kg?", "b": "20 kg (vì 1 tạ = 100 kg)."}, {"id": "b6c3", "img": "", "svg": "b6c3x", "f": "1 lạng bằng bao nhiêu?", "b": "100 g = 0,1 kg."}, {"id": "b6c4", "img": "../hinh-anh/khtn/fc-sua-chinh-can.webp", "svg": "", "f": "Trước khi cân phải làm gì với cân?", "b": "Hiệu chỉnh cân về vạch 0."}, {"id": "b6c5", "img": "", "svg": "b6c5x", "f": "Cân 257,5 g thì chọn những quả cân nào?", "b": "200 g + 50 g + 5 g + 2 g + 500 mg."}], "bai7": [{"id": "b7c1", "img": "", "svg": "b7c1x", "f": "Đơn vị đo thời gian là gì?", "b": "Giây (s)."}, {"id": "b7c2", "img": "", "svg": "b7c2x", "f": "1 ngày bằng bao nhiêu giờ?", "b": "24 giờ."}, {"id": "b7c3", "img": "../hinh-anh/khtn/fc-bai7-chay-dien-kinh.webp", "svg": "", "f": "Đo thời gian chạy 100 m dùng đồng hồ nào?", "b": "Đồng hồ bấm giây."}, {"id": "b7c4", "img": "", "svg": "b7c4x", "f": "1 giờ bằng bao nhiêu giây?", "b": "3600 giây."}], "bai8": [{"id": "b8c1", "img": "", "svg": "b8c1x", "f": "Nhiệt độ nước đá đang tan là bao nhiêu °C?", "b": "0 °C."}, {"id": "b8c2", "img": "", "svg": "b8c2x", "f": "Nhiệt độ nước đang sôi theo thang °F?", "b": "212 °F."}, {"id": "b8c3", "img": "", "svg": "b8c3x", "f": "Công thức đổi °C sang °F?", "b": "°F = °C × 1,8 + 32."}, {"id": "b8c4", "img": "", "svg": "b8c4x", "f": "22 °C đổi sang °F bằng bao nhiêu?", "b": "71,6 °F."}, {"id": "b8c5", "img": "", "svg": "b8c5", "f": "Nhiệt kế y tế thủy ngân có GHĐ và ĐCNN bao nhiêu?", "b": "GHĐ 42°C, ĐCNN 0,1°C."}], "bai10": [{"id": "b10c1", "img": "", "svg": "states", "f": "Chất có những thể nào?", "b": "Ba thể: rắn, lỏng, khí."}, {"id": "b10c2", "img": "", "svg": "change", "f": "Nóng chảy là sự chuyển thể nào?", "b": "Từ thể rắn sang thể lỏng."}, {"id": "b10c3", "img": "../hinh-anh/khtn/fc-sua-may.webp", "svg": "", "f": "Mây được tạo thành do hiện tượng gì?", "b": "Hơi nước ngưng tụ trên cao."}, {"id": "b10c4", "img": "../hinh-anh/khtn/fc-sua-soi-bay-hoi.webp", "svg": "", "f": "Sôi khác bay hơi ở điểm nào?", "b": "Sôi xảy ra ở một nhiệt độ xác định; bay hơi xảy ra ở mọi nhiệt độ, chỉ trên bề mặt."}, {"id": "b10c5", "img": "", "svg": "b10c5x", "f": "Thể khí có đặc điểm gì nổi bật?", "b": "Không có hình dạng và thể tích xác định, lan tỏa theo mọi hướng."}], "bai9": [{"id": "b9c1", "img": "../hinh-anh/khtn/fc-sua-gi-sat.webp", "svg": "", "f": "Tính chất hóa học của chất là gì?", "b": "Khả năng biến đổi thành chất khác (tạo ra chất mới)."}, {"id": "b9c2", "img": "../hinh-anh/khtn/fc-bai9-duong-chay.webp", "svg": "", "f": "Đun đường đến cháy đen thể hiện tính chất gì?", "b": "Tính chất hóa học — vì có chất mới tạo thành."}, {"id": "b9c3", "img": "", "svg": "b9c3", "f": "Vật thể tự nhiên khác vật thể nhân tạo thế nào? Cho ví dụ.", "b": "Vật thể tự nhiên có sẵn trong tự nhiên (VD: con voi, cây dừa); vật thể nhân tạo do con người tạo ra (VD: bàn, ghế, đồng hồ)."}, {"id": "b9c4", "img": "", "svg": "b9c4", "f": "Than cháy tạo ra chất gì? Thể hiện tính chất nào?", "b": "Than cháy tạo thành khí carbon dioxide (CO₂) — thể hiện tính chất hóa học, vì có chất mới tạo thành."}, {"id": "b9c5", "img": "", "svg": "b9c5", "f": "Cho đá vôi vào giấm ăn thấy sủi bọt khí, thể hiện tính chất gì?", "b": "Tính chất hóa học — vì đá vôi tác dụng với giấm tạo ra chất mới (khí thoát ra)."}], "bai11": [{"id": "b11c1", "img": "", "svg": "b11c1x", "f": "Oxygen chiếm khoảng bao nhiêu % không khí?", "b": "Khoảng 21%."}, {"id": "b11c2", "img": "", "svg": "b11c2x", "f": "Nitrogen chiếm khoảng bao nhiêu % không khí?", "b": "Khoảng 78%."}, {"id": "b11c3", "img": "../hinh-anh/khtn/fc-sua-chay-xang-cat.webp", "svg": "", "f": "Can xăng bốc cháy thì dập lửa bằng gì?", "b": "Dùng cát đổ trùm lên (hoặc bình chữa cháy) — không dùng nước."}, {"id": "b11c4", "img": "../hinh-anh/khtn/fc-sua-xang-tren-nuoc.webp", "svg": "", "f": "Vì sao không dùng nước dập cháy xăng?", "b": "Xăng nhẹ hơn nước và không tan, nước làm xăng loang ra, cháy lan rộng hơn."}, {"id": "b11c5", "img": "", "svg": "b11c5x", "f": "Dùng bếp gas sao cho tiết kiệm?", "b": "Điều chỉnh ngọn lửa phù hợp với nồi và nhu cầu đun nấu."}], "bai18": [{"id": "b18c1", "img": "", "svg": "cell", "f": "Đơn vị cấu tạo nên mọi sinh vật là gì?", "b": "Tế bào."}, {"id": "b18c2", "img": "", "svg": "b18c2x", "f": "Trung tâm điều khiển mọi hoạt động của tế bào?", "b": "Nhân tế bào."}, {"id": "b18c3", "img": "../hinh-anh/khtn/fc-bai12-sinh-vat-don-bao.webp", "svg": "", "f": "Kể hai sinh vật đơn bào.", "b": "Tảo lục và vi khuẩn lam."}, {"id": "b18c4", "img": "", "svg": "b18c4x", "f": "Các cấp độ tổ chức của cơ thể theo thứ tự?", "b": "Tế bào → mô → cơ quan → hệ cơ quan → cơ thể."}, {"id": "b18c5", "img": "../hinh-anh/khtn/fc-sua-he-choi-he-re.webp", "svg": "", "f": "Thực vật có hai hệ cơ quan nào?", "b": "Hệ chồi và hệ rễ."}, {"id": "b18c6", "img": "../hinh-anh/khtn/fc-sua-te-bao-nhan-so.webp", "svg": "", "f": "\"Vùng nhân\" là đặc điểm của tế bào loại nào?", "b": "Tế bào nhân sơ (tế bào nhân thực không có vùng nhân)."}], "bai40": [{"id": "b40c1", "img": "../hinh-anh/khtn/fc-bai13-day-keo.webp", "svg": "", "f": "Lực là gì?", "b": "Tác dụng đẩy, kéo của vật này lên vật khác."}, {"id": "b40c2", "img": "../hinh-anh/khtn/fc-bai13-qua-ta-roi.webp", "svg": "", "f": "Trọng lực luôn có chiều thế nào?", "b": "Hướng xuống dưới, về phía Trái Đất."}, {"id": "b40c3", "img": "../hinh-anh/khtn/fc-sua-luc-can-bang.webp", "svg": "", "f": "Hai lực cân bằng cần đủ điều kiện gì?", "b": "Cùng tác dụng lên một vật, cùng phương, ngược chiều, cùng độ lớn."}, {"id": "b40c4", "img": "", "svg": "b40c4x", "f": "Đơn vị đo lực là gì?", "b": "Niutơn (N)."}, {"id": "b40c5", "img": "../hinh-anh/khtn/bai13-luc-ke.webp", "svg": "", "f": "Lực kế thường dùng có GHĐ và ĐCNN bao nhiêu?", "b": "GHĐ 10 N, ĐCNN 0,2 N."}, {"id": "b40c6", "img": "", "svg": "b40c6x", "f": "Treo 150 g kim chỉ vạch 3, treo 100 g chỉ vạch mấy?", "b": "Vạch thứ 2 (mỗi vạch ứng với 50 g)."}],
"bai12": [{"id": "b12c1", "img": "", "svg": "b12c1", "f": "Vật liệu là gì?", "b": "Con người dùng vật liệu để tạo ra các vật dụng (vật liệu tự nhiên: đá, gỗ, đất…; vật liệu do con người chế tạo: thuỷ tinh, nhựa, gốm sứ, kim loại…)."}, {"id": "b12c2", "img": "", "svg": "b12c2", "f": "Kim loại có tính chất và ứng dụng nào?", "b": "Cứng, bền, dẫn điện và dẫn nhiệt tốt — làm dây điện, nồi, khung cửa."}, {"id": "b12c3", "img": "", "svg": "b12c3x", "f": "Nhựa có tính chất gì? Vì sao cần hạn chế đồ nhựa dùng một lần?", "b": "Nhẹ, bền, cách điện, dễ tạo hình; nhựa khó phân hủy nên gây ô nhiễm môi trường."}, {"id": "b12c4", "img": "", "svg": "b12c4", "f": "Cao su và thủy tinh khác nhau ở tính chất nào?", "b": "Cao su đàn hồi, không thấm nước; thủy tinh trong suốt nhưng dễ vỡ."}, {"id": "b12c5", "img": "../hinh-anh/khtn/bai12-bieu-tuong-tai-che.png", "svg": "", "f": "Muốn dùng vật liệu tiết kiệm và bảo vệ môi trường thì làm gì?", "b": "Chọn đúng vật liệu, tái sử dụng và tái chế theo mô hình 3R."}], "bai13": [{"b": "Chất hoặc hỗn hợp được con người lấy từ tự nhiên hoặc tạo ra, dùng làm đầu vào để chế biến thành vật liệu hoặc sản phẩm khác (VD: đá vôi, quặng sắt, dầu mỏ).", "f": "Nguyên liệu là gì?", "id": "b13c1", "img": "", "svg": "b13c1"}, {"b": "Để luyện gang và thép, là vật liệu làm cầu, nhà, xe.", "f": "Quặng sắt dùng để làm gì?", "id": "b13c2", "img": "../hinh-anh/khtn/fc-bai13-lo-ren.webp", "svg": ""}, {"b": "Là nguyên liệu chính để sản xuất xi măng, dùng xây nhà.", "f": "Đá vôi dùng để làm gì?", "id": "b13c3", "img": "", "svg": "b13c3"}, {"b": "Vì nhiều nguyên liệu không tái tạo, dùng lãng phí sẽ cạn kiệt và làm hại môi trường.", "f": "Vì sao phải dùng nguyên liệu tiết kiệm?", "id": "b13c5", "img": "", "svg": "b13c5x"}],
"bai14": [{"b": "Là chất khi cháy sẽ tỏa ra năng lượng, chủ yếu là nhiệt. Ví dụ: than, xăng, gas khi cháy đều tỏa nhiệt để đun nấu, chạy máy.", "f": "Nhiên liệu là gì?", "id": "b14c1", "img": "", "svg": "b14c1"}, {"b": "Rắn: than, củi; lỏng: xăng, dầu; khí: gas, biogas.", "f": "Kể 3 dạng nhiên liệu và ví dụ mỗi dạng?", "id": "b14c2", "img": "", "svg": "b14c2"}, {"b": "Là nhiên liệu hình thành từ xác sinh vật bị vùi lấp hàng triệu năm. Ví dụ: than đá, dầu mỏ, khí thiên nhiên.", "f": "Nhiên liệu hóa thạch là gì?", "id": "b14c3", "img": "", "svg": "b14c3"}, {"b": "Vì chúng hình thành rất lâu, con người dùng hết thì không có lại trong thời gian ngắn.", "f": "Vì sao than đá, dầu mỏ gọi là không tái tạo?", "id": "b14c4", "img": "", "svg": "b14c4"}, {"b": "Dùng xong phải khóa van gas, vì gas rò rỉ gặp lửa có thể gây cháy nổ.", "f": "Dùng bếp gas an toàn cần nhớ gì?", "id": "b14c5", "img": "", "svg": "b14c5x"}, {"b": "Thủy điện, gió, năng lượng mặt trời, thủy triều, năng lượng sinh học, địa nhiệt.", "f": "Kể tên một số nguồn năng lượng thay thế nhiên liệu hóa thạch.", "id": "b14c6", "img": "", "svg": "b14c6"}],
"bai15": [{"b": "Là thức ăn giàu tinh bột, dùng làm thức ăn chính hằng ngày. Ví dụ: gạo, ngô, khoai, sắn.", "f": "Lương thực là gì?", "id": "b15c1", "img": "", "svg": "b15c1"}, {"b": "Là tên gọi chung các thức ăn cung cấp chất dinh dưỡng cho cơ thể. Ví dụ: thịt, cá, trứng, rau, quả.", "f": "Thực phẩm là gì?", "id": "b15c2", "img": "", "svg": "b15c2"}, {"b": "Có nhiều trong thịt, cá, trứng, sữa, đậu; giúp cơ thể lớn lên và khỏe mạnh.", "f": "Chất đạm có nhiều ở đâu, để làm gì?", "id": "b15c3", "img": "", "svg": "b15c3"}, {"b": "Vì rau, quả có nhiều vitamin, chất khoáng và chất xơ, giúp cơ thể khỏe và tiêu hóa tốt.", "f": "Vì sao phải ăn rau, quả mỗi ngày?", "id": "b15c4", "img": "", "svg": "b15c4"}, {"b": "Chọn đồ tươi, còn hạn dùng, rõ nguồn gốc và rửa sạch trước khi ăn.", "f": "Chọn thực phẩm an toàn cần nhớ gì?", "id": "b15c5", "img": "", "svg": "b15c5"}],
"bai16": [{"b": "Là hai hay nhiều chất trộn lẫn với nhau, mỗi chất vẫn giữ tính chất riêng. Ví dụ: nước muối là hỗn hợp của muối và nước.", "f": "Hỗn hợp là gì?", "id": "b16c1", "img": "", "svg": "b16c1"}, {"b": "Là hỗn hợp trộn đều, không nhìn rõ từng chất riêng. Ví dụ: nước đường đã khuấy tan, không khí.", "f": "Hỗn hợp đồng nhất là gì?", "id": "b16c2", "img": "", "svg": "b16c2"}, {"b": "Là hỗn hợp nhìn rõ từng chất riêng. Ví dụ: nước pha dầu, nước lẫn cát.", "f": "Hỗn hợp không đồng nhất là gì?", "id": "b16c3", "img": "", "svg": "b16c3"}, {"b": "Là hỗn hợp đồng nhất của chất tan trong dung môi. Ví dụ: nước muối thì muối là chất tan, nước là dung môi.", "f": "Dung dịch là gì?", "id": "b16c4", "img": "", "svg": "b16c4x"}, {"b": "Là hỗn hợp không đồng nhất, có các hạt chất rắn lơ lửng trong chất lỏng. Ví dụ: nước lẫn cát, nước bùn.", "f": "Huyền phù là gì?", "id": "b16c5", "img": "", "svg": "b16c5"}],
"bai17": [{"b": "Để tách chất rắn không tan ra khỏi chất lỏng. Ví dụ: lọc nước lẫn cát bằng giấy lọc, cát bị giữ lại, nước chảy qua.", "f": "Lọc dùng để tách hỗn hợp nào?", "id": "b17c1", "img": "", "svg": "b17c1"}, {"b": "Là cách đun nóng cho chất lỏng bay hơi, còn lại chất tan. Ví dụ: cô cạn nước muối thì nước bay hơi, muối ở lại.", "f": "Cô cạn là gì?", "id": "b17c2", "img": "", "svg": "b17c2"}, {"b": "Là cách để yên cho chất rắn nặng hơn lắng xuống đáy, rồi gạn lấy phần chất lỏng phía trên. Ví dụ: để yên nước lẫn cát, cát lắng xuống đáy rồi gạn lấy nước trong.", "f": "Lắng là gì? Cho ví dụ.", "id": "b17c3", "img": "", "svg": "b17c3"}, {"b": "Để yên cho dầu nổi lên trên rồi gạn lấy lớp dầu, vì dầu nhẹ hơn nước và không tan trong nước.", "f": "Muốn tách dầu khỏi nước thì làm sao?", "id": "b17c4", "img": "", "svg": "b17c4x"}, {"b": "Dựa vào tính chất khác nhau của các chất: chất rắn không tan thì lọc, chất tan thì cô cạn, hai chất lỏng không tan vào nhau thì chiết.", "f": "Chọn cách tách dựa vào đâu?", "id": "b17c5", "img": "", "svg": "b17c5x"}, {"b": "Là cách tách các chất lỏng không tan vào nhau ra khỏi nhau bằng phễu chiết. Ví dụ: tách dầu ăn khỏi nước bằng phễu chiết.", "f": "Chiết là gì? Cho ví dụ.", "id": "b17c6", "img": "", "svg": "b17c6"}],
"bai19": [{"b": "Là đơn vị nhỏ nhất cấu tạo nên cơ thể sống và thực hiện chức năng sống. Ví dụ: cơ thể người được tạo nên từ rất nhiều tế bào.", "f": "Tế bào là gì?", "id": "b19c1", "img": "", "svg": "b19c1"}, {"b": "Bao bọc, bảo vệ tế bào và kiểm soát các chất đi ra, đi vào tế bào.", "f": "Màng tế bào làm gì?", "id": "b19c2", "img": "", "svg": "b19c2"}, {"b": "Điều khiển mọi hoạt động sống của tế bào và chứa thông tin di truyền.", "f": "Nhân tế bào làm gì?", "id": "b19c3", "img": "", "svg": "b19c3x"}, {"b": "Là thành phần chứa chất diệp lục giúp cây quang hợp, chỉ có ở tế bào thực vật.", "f": "Lục lạp là gì, có ở đâu?", "id": "b19c4", "img": "", "svg": "b19c4"}, {"b": "Tế bào thực vật có thành tế bào, lục lạp và không bào lớn; tế bào động vật không có ba thành phần này.", "f": "Tế bào thực vật khác tế bào động vật thế nào?", "id": "b19c5", "img": "", "svg": "b19c5"}],
"bai20": [{"b": "Là tế bào tăng kích thước và khối lượng nhờ lấy chất dinh dưỡng từ môi trường.", "f": "Tế bào lớn lên là gì?", "id": "b20c1", "img": "", "svg": "b20c1"}, {"b": "Bằng cách phân chia: một tế bào mẹ phân chia thành hai tế bào con giống nhau.", "f": "Tế bào sinh sản bằng cách nào?", "id": "b20c2", "img": "", "svg": "b20c2"}, {"b": "Nhân tế bào phân chia trước, sau đó chất tế bào phân chia.", "f": "Khi phân chia, phần nào chia trước?", "id": "b20c3", "img": "", "svg": "b20c3"}, {"b": "Tế bào con lớn lên, rồi lại phân chia thành tế bào mới.", "f": "Tế bào con sau khi sinh ra sẽ thế nào?", "id": "b20c4", "img": "", "svg": "b20c4x"}, {"b": "Cơ thể lớn lên và thay thế các tế bào già, tế bào hỏng, ví dụ vết thương ngoài da lành lại.", "f": "Nhờ phân chia tế bào mà cơ thể được gì?", "id": "b20c5", "img": "", "svg": "b20c5x"}],
"bai21": [{"b": "Kính hiển vi, vì tế bào rất nhỏ, mắt thường không nhìn thấy được.", "f": "Quan sát tế bào cần dụng cụ chính nào?", "id": "b21c1", "img": "", "svg": "b21c1"}, {"b": "Biểu bì hành tây, là lớp màng mỏng bóc từ củ hành, tế bào xếp sát nhau.", "f": "Mẫu thực vật thường dùng là gì?", "id": "b21c2", "img": "", "svg": "b21c2"}, {"b": "Tế bào niêm mạc miệng, lấy nhẹ ở mặt trong má.", "f": "Mẫu động vật thường dùng là gì?", "id": "b21c3", "img": "", "svg": "b21c3"}, {"b": "Đặt nghiêng từ từ xuống mẫu, để tránh bọt khí lọt vào làm mờ hình ảnh.", "f": "Đậy lamen thế nào cho đúng?", "id": "b21c4", "img": "", "svg": "b21c4"}, {"b": "Tế bào thực vật có thành tế bào rõ, hình đa giác xếp sát nhau; tế bào động vật không có thành tế bào.", "f": "Phân biệt tế bào thực vật và động vật khi quan sát?", "id": "b21c5", "img": "", "svg": "b21c5"}],
"bai22": [{"id": "b22c1", "img": "", "svg": "b22c1x", "f": "Cơ thể sinh vật là gì?", "b": "Một sinh vật hoàn chỉnh, có các hoạt động sống."}, {"id": "b22c2", "img": "", "svg": "b22c2", "f": "Cơ thể đơn bào là gì? Cho ví dụ.", "b": "Chỉ gồm một tế bào duy nhất, thực hiện mọi hoạt động sống; ví dụ vi khuẩn, trùng giày, tảo lục."}, {"id": "b22c3", "img": "", "svg": "b22c3", "f": "Cơ thể đa bào là gì? Cho ví dụ.", "b": "Gồm nhiều tế bào phân công nhiệm vụ, phối hợp với nhau; ví dụ người, cây lúa, con gà."}, {"id": "b22c4", "img": "", "svg": "b22c4", "f": "Các tế bào trong cơ thể đa bào làm việc như thế nào?", "b": "Mỗi loại tế bào làm một nhiệm vụ riêng và phối hợp với nhau."}, {"id": "b22c5", "img": "", "svg": "b22c5x", "f": "Muốn quan sát sinh vật đơn bào thường dùng dụng cụ gì? Vì sao?", "b": "Kính hiển vi, vì sinh vật đơn bào rất nhỏ, mắt thường khó thấy."}], "bai23": [{"id": "b23c1", "img": "", "svg": "b23c1", "f": "Các cấp độ tổ chức của cơ thể đa bào theo thứ tự từ nhỏ đến lớn là gì?", "b": "Tế bào → mô → cơ quan → hệ cơ quan → cơ thể."}, {"id": "b23c2", "img": "", "svg": "b23c2", "f": "Mô là gì? Cho ví dụ.", "b": "Tập hợp các tế bào giống nhau, cùng thực hiện một chức năng; ví dụ mô cơ, mô biểu bì."}, {"id": "b23c3", "img": "", "svg": "b23c3", "f": "Cơ quan là gì? Cho ví dụ.", "b": "Nhiều mô hợp lại, cùng thực hiện một chức năng nhất định; ví dụ dạ dày, tim, lá."}, {"id": "b23c4", "img": "", "svg": "b23c4", "f": "Hệ cơ quan là gì? Cho ví dụ ở người.", "b": "Nhiều cơ quan phối hợp với nhau; ví dụ hệ tiêu hóa, hệ tuần hoàn."}, {"id": "b23c5", "img": "", "svg": "b23c5x", "f": "Cơ thể thực vật có những hệ cơ quan nào?", "b": "Hệ chồi (thân, lá, hoa, quả) và hệ rễ."}], "bai24": [{"b": "Là cơ thể chỉ gồm một tế bào duy nhất, ví dụ trùng giày, vi khuẩn.", "f": "Cơ thể đơn bào là gì?", "id": "b24c1", "img": "", "svg": "b24c1x"}, {"b": "Là cơ thể gồm nhiều tế bào phối hợp với nhau, ví dụ người, cây lúa, con gà.", "f": "Cơ thể đa bào là gì?", "id": "b24c2", "img": "", "svg": "b24c2x"}, {"b": "Bằng lông bơi rung động quanh cơ thể, giúp nó bơi trong nước.", "f": "Trùng giày di chuyển bằng gì?", "id": "b24c3", "img": "", "svg": "b24c3"}, {"b": "Đa bào có nhiều loại tế bào, mỗi loại làm một nhiệm vụ riêng; đơn bào chỉ có một tế bào làm mọi việc.", "f": "Đa bào khác đơn bào ở điểm nào?", "id": "b24c4", "img": "", "svg": "b24c4x"}, {"b": "Lấy mẫu nước ao, hồ có váng xanh hoặc rơm rạ ngâm, vì trùng giày sống trong nước đó.", "f": "Quan sát trùng giày lấy mẫu ở đâu?", "id": "b24c5", "img": "", "svg": "b24c5"}],
"bai25": [{"id": "b25c1", "img": "", "svg": "b25c1", "f": "Phân loại sinh vật là gì?", "b": "Xếp sinh vật vào các nhóm theo đặc điểm chung."}, {"id": "b25c2", "img": "", "svg": "b25c2", "f": "Bậc phân loại lớn nhất là gì?", "b": "Giới."}, {"id": "b25c3", "img": "", "svg": "b25c3", "f": "Bậc phân loại nhỏ nhất là gì?", "b": "Loài."}, {"id": "b25c4", "img": "", "svg": "b25c4x", "f": "Tên khoa học của loài gồm những gì?", "b": "Tên chi + tên loài, ví dụ Homo sapiens."}, {"id": "b25c5", "img": "", "svg": "b25c5", "f": "Kể tên 5 giới sinh vật.", "b": "Khởi sinh, Nguyên sinh, Nấm, Thực vật, Động vật."}],
"bai26": [{"id": "b26c1", "img": "", "svg": "b26c1", "f": "Khóa lưỡng phân là gì?", "b": "Bảng các cặp đặc điểm đối lập nhau, dùng để nhận biết sinh vật."}, {"id": "b26c2", "img": "", "svg": "b26c2x", "f": "Mỗi bước của khóa có mấy lựa chọn?", "b": "2 lựa chọn đối lập nhau."}, {"id": "b26c3", "img": "", "svg": "b26c3x", "f": "Dùng khóa lưỡng phân bắt đầu từ đâu?", "b": "Từ bước đầu tiên, chọn đặc điểm đúng với mẫu vật rồi đi tiếp."}, {"id": "b26c4", "img": "", "svg": "b26c4", "f": "Chọn sai một bước thì sao?", "b": "Đi nhầm nhánh, ra tên loài sai."}, {"id": "b26c5", "img": "", "svg": "b26c5x", "f": "Chữ lưỡng trong lưỡng phân nghĩa là gì?", "b": "Là hai: mỗi bước chia hai nhánh."}],
"bai27": [{"id": "b27c1", "img": "", "svg": "b27c1x", "f": "Vi khuẩn có nhân hoàn chỉnh không?", "b": "Không, vi khuẩn chưa có nhân hoàn chỉnh."}, {"id": "b27c2", "img": "", "svg": "b27c2", "f": "Vi khuẩn sinh sản bằng cách nào?", "b": "Phân đôi: một tế bào tách thành hai."}, {"id": "b27c3", "img": "", "svg": "b27c3", "f": "Kể 3 dạng hình của vi khuẩn.", "b": "Hình cầu, hình que, hình xoắn."}, {"id": "b27c4", "img": "", "svg": "b27c4", "f": "Vi khuẩn lactic dùng để làm gì?", "b": "Làm sữa chua, muối dưa."}, {"id": "b27c5", "img": "", "svg": "b27c5", "f": "Vì sao phải rửa tay trước khi ăn?", "b": "Để giảm vi khuẩn gây bệnh từ tay vào thức ăn."}],
"bai28": [{"id": "b28c1", "img": "", "svg": "b28c1x", "f": "Sữa chua chua là do chất nào?", "b": "Axit lactic do vi khuẩn lactic tạo ra."}, {"id": "b28c2", "img": "", "svg": "b28c2", "f": "Ủ sữa chua ở nhiệt độ nào?", "b": "Ấm khoảng 40°C."}, {"id": "b28c3", "img": "", "svg": "b28c3", "f": "Quan sát vi khuẩn bằng dụng cụ gì?", "b": "Kính hiển vi."}, {"id": "b28c4", "img": "", "svg": "b28c4", "f": "Sữa chua làm xong để ở đâu?", "b": "Ngăn mát tủ lạnh."}, {"id": "b28c5", "img": "", "svg": "b28c5x", "f": "Vì sao không được nếm mẫu quan sát?", "b": "Vì mẫu có thể chứa vi khuẩn lạ gây bệnh."}],
"bai29": [{"id": "b29c1", "img": "", "svg": "b29c1x", "f": "Virus có phải là tế bào không?", "b": "Không, virus chưa có cấu tạo tế bào hoàn chỉnh."}, {"id": "b29c2", "img": "", "svg": "b29c2", "f": "Virus gồm những thành phần nào?", "b": "Vỏ protein và lõi axit nucleic."}, {"id": "b29c3", "img": "", "svg": "b29c3x", "f": "Virus nhân lên ở đâu?", "b": "Trong tế bào chủ, nhờ bộ máy của tế bào chủ."}, {"id": "b29c4", "img": "", "svg": "b29c4x", "f": "Kể 2 bệnh do virus gây ra.", "b": "Cúm và sởi (hoặc COVID-19, thủy đậu)."}, {"id": "b29c5", "img": "", "svg": "b29c5x", "f": "Vì sao cảm cúm không nên uống kháng sinh?", "b": "Vì kháng sinh không diệt được virus."}],
"bai30": [{"id": "b30c1", "img": "", "svg": "b30c1x", "f": "Nguyên sinh vật là đơn bào hay đa bào?", "b": "Đơn bào, có nhân hoàn chỉnh."}, {"id": "b30c2", "img": "", "svg": "b30c2", "f": "Trùng giày di chuyển bằng gì?", "b": "Lông bơi phủ quanh cơ thể."}, {"id": "b30c3", "img": "", "svg": "b30c3", "f": "Tảo đơn bào có ích gì?", "b": "Quang hợp tạo oxygen, làm thức ăn cho sinh vật nước."}, {"id": "b30c4", "img": "", "svg": "b30c4", "f": "Trùng sốt rét lây sang người qua đâu?", "b": "Qua muỗi đốt."}, {"id": "b30c5", "img": "", "svg": "b30c5", "f": "Nguyên sinh vật có nhân hoàn chỉnh không?", "b": "Có, đó là tế bào nhân thực."}],
"bai31": [{"id": "b31c1", "img": "", "svg": "b31c1", "f": "Lấy mẫu nguyên sinh vật ở đâu?", "b": "Nước ao, hồ hoặc vũng nước đọng có váng."}, {"id": "b31c2", "img": "", "svg": "b31c2", "f": "Quan sát nguyên sinh vật bằng dụng cụ gì?", "b": "Kính hiển vi, nhỏ mẫu lên lam kính."}, {"id": "b31c3", "img": "", "svg": "b31c3", "f": "Trùng giày bơi bằng gì?", "b": "Lông bơi phủ quanh cơ thể."}, {"id": "b31c4", "img": "", "svg": "b31c4x", "f": "Quan sát xong phải làm gì?", "b": "Đổ bỏ mẫu đúng chỗ, rửa tay, vệ sinh dụng cụ."}, {"id": "b31c5", "img": "", "svg": "b31c5x", "f": "Lấy mẫu nước ao cần chú ý gì?", "b": "Đi cùng người lớn, không lội sâu, không uống nước mẫu."}],
"bai32": [{"id": "b32c1", "img": "", "svg": "b32c1x", "f": "Nấm có quang hợp không?", "b": "Không, nấm không có chất diệp lục nên không quang hợp."}, {"id": "b32c2", "img": "", "svg": "b32c2", "f": "Nấm mũ gồm những bộ phận nào?", "b": "Mũ, phiến, cuống và sợi nấm."}, {"id": "b32c3", "img": "", "svg": "b32c3", "f": "Nấm sinh sản bằng gì?", "b": "Bào tử; nấm men thì nảy chồi."}, {"id": "b32c4", "img": "", "svg": "b32c4", "f": "Nấm men dùng để làm gì?", "b": "Làm bánh mì nở và ủ rượu."}, {"id": "b32c5", "img": "", "svg": "b32c5", "f": "Vì sao không được ăn nấm lạ?", "b": "Vì nấm độc giống nấm ăn, ăn nhầm gây ngộ độc chết người."}],
"bai33": [{"id": "b33c1", "img": "", "svg": "b33c1", "f": "Nấm mũ có những phần nào?", "b": "Mũ, phiến dưới mũ, cuống và sợi nấm."}, {"id": "b33c2", "img": "", "svg": "b33c2", "f": "Sợi nấm để làm gì?", "b": "Hút chất dinh dưỡng nuôi nấm."}, {"id": "b33c3", "img": "", "svg": "b33c3", "f": "Phiến nấm chứa gì?", "b": "Bào tử để sinh sản."}, {"id": "b33c4", "img": "", "svg": "b33c4", "f": "Vì sao nấm mọc nhiều sau mưa?", "b": "Vì ẩm ướt giúp bào tử nảy mầm."}, {"id": "b33c5", "img": "", "svg": "b33c5", "f": "Có phân biệt nấm độc bằng mắt được không?", "b": "Không chắc chắn được, không tự hái nấm lạ về ăn."}],
"bai34": [{"id": "b34c1", "img": "", "svg": "b34c1", "f": "Thực vật tự dưỡng bằng cách nào?", "b": "Nhờ quang hợp ở lá."}, {"id": "b34c2", "img": "", "svg": "b34c2", "f": "Quang hợp cần những gì?", "b": "Ánh sáng, nước và khí carbon dioxide; tạo ra oxygen."}, {"id": "b34c3", "img": "", "svg": "b34c3", "f": "Kể 4 nhóm thực vật.", "b": "Rêu, dương xỉ, hạt trần, hạt kín."}, {"id": "b34c4", "img": "", "svg": "b34c4", "f": "Hạt trần khác hạt kín thế nào?", "b": "Hạt trần nằm trần trên lá noãn; hạt kín nằm trong quả."}, {"id": "b34c5", "img": "", "svg": "b34c5x", "f": "Thực vật có vai trò gì?", "b": "Tạo oxygen, thức ăn, nơi ở và giữ đất."}],
"bai35": [{"id": "b35c1", "img": "", "svg": "b35c1", "f": "Rêu có rễ thật không?", "b": "Không, rêu chỉ có rễ giả."}, {"id": "b35c2", "img": "", "svg": "b35c2", "f": "Dương xỉ sinh sản bằng gì?", "b": "Bào tử ở mặt dưới lá."}, {"id": "b35c3", "img": "", "svg": "b35c3", "f": "Thông thuộc nhóm nào?", "b": "Hạt trần."}, {"id": "b35c4", "img": "", "svg": "b35c4x", "f": "Lúa thuộc nhóm nào?", "b": "Hạt kín."}, {"id": "b35c5", "img": "", "svg": "b35c5x", "f": "Phân biệt nhóm thực vật dựa vào đâu?", "b": "Rễ, thân, lá, hoa, quả, hạt và cách sinh sản."}],
"bai36": [{"id": "b36c1", "img": "", "svg": "b36c1x", "f": "Động vật khác thực vật ở điểm nào?", "b": "Động vật dị dưỡng và di chuyển được; thực vật tự dưỡng và sống cố định."}, {"id": "b36c2", "img": "", "svg": "b36c2", "f": "Kể 3 nhóm động vật không xương sống.", "b": "Giun, thân mềm (ốc), chân khớp (tôm, cua, côn trùng)."}, {"id": "b36c3", "img": "", "svg": "b36c3x", "f": "Kể 5 lớp động vật có xương sống.", "b": "Cá, lưỡng cư, bò sát, chim, thú."}, {"id": "b36c4", "img": "", "svg": "b36c4", "f": "Cá thở bằng gì?", "b": "Bằng mang."}, {"id": "b36c5", "img": "", "svg": "b36c5", "f": "Thú nuôi con bằng gì?", "b": "Bằng sữa."}],
"bai37": [{"id": "b37c1", "img": "", "svg": "b37c1", "f": "Quan sát động vật ngoài thiên nhiên bằng cách nào?", "b": "Quan sát trực tiếp, ghi chép, chụp ảnh, không bắt giữ."}, {"id": "b37c2", "img": "", "svg": "b37c2", "f": "Chim khác dơi ở điểm nào?", "b": "Chim có lông vũ, đẻ trứng; dơi là thú, có lông mao, đẻ con."}, {"id": "b37c3", "img": "", "svg": "b37c3", "f": "Thấy tổ chim thì làm gì?", "b": "Đứng xa quan sát, không chạm vào tổ, không phá tổ."}, {"id": "b37c4", "img": "", "svg": "b37c4", "f": "Ghi chép những gì khi quan sát?", "b": "Tên, nơi gặp, đặc điểm, số lượng, hành vi."}, {"id": "b37c5", "img": "", "svg": "b37c5", "f": "Quan sát động vật cần chú ý an toàn gì?", "b": "Đi cùng người lớn, tránh thú dữ, rắn, tổ ong."}],
"bai38": [{"id": "b38c1", "img": "", "svg": "b38c1", "f": "Đa dạng sinh học là gì?", "b": "Sự phong phú về số loài, số cá thể và môi trường sống."}, {"id": "b38c2", "img": "", "svg": "b38c2", "f": "Vì sao đa dạng sinh học suy giảm?", "b": "Phá rừng, ô nhiễm, săn bắt quá mức, biến đổi khí hậu."}, {"id": "b38c3", "img": "", "svg": "b38c3", "f": "Kể 2 cách bảo vệ đa dạng sinh học.", "b": "Lập khu bảo tồn và trồng rừng (hoặc cấm săn bắt loài quý hiếm)."}, {"id": "b38c4", "img": "", "svg": "b38c4", "f": "Loài đặc hữu là gì?", "b": "Loài chỉ sống ở một nơi nhất định."}, {"id": "b38c5", "img": "", "svg": "b38c5x", "f": "Em có thể làm gì để bảo vệ?", "b": "Không mua bán động vật hoang dã, không xả rác, trồng cây."}],
"bai39": [{"id": "b39c1", "img": "", "svg": "b39c1x", "f": "Tìm hiểu sinh vật ngoài thiên nhiên gồm mấy bước?", "b": "Chọn địa điểm, quan sát, ghi chép, báo cáo."}, {"id": "b39c2", "img": "", "svg": "b39c2", "f": "Không biết tên sinh vật thì làm sao?", "b": "Dùng khóa lưỡng phân, hỏi thầy cô, đối chiếu sách."}, {"id": "b39c3", "img": "", "svg": "b39c3", "f": "Báo cáo gồm những gì?", "b": "Tên sinh vật, nơi gặp, đặc điểm, hình vẽ hoặc ảnh."}, {"id": "b39c4", "img": "", "svg": "b39c4x", "f": "Cần chuẩn bị gì khi đi tìm hiểu?", "b": "Sổ, bút, kính lúp, máy ảnh, mũ, nước uống."}, {"id": "b39c5", "img": "", "svg": "b39c5x", "f": "Vì sao không phá hoại khi tìm hiểu?", "b": "Vì sinh vật mất nơi sống, lần sau không còn gì quan sát."}],
"bai41": [{"id": "b41c1", "img": "", "svg": "b41c1x", "f": "Lực được mô tả bằng mấy yếu tố?", "b": "4 yếu tố: điểm đặt, phương, chiều, độ lớn."}, {"id": "b41c2", "img": "", "svg": "b41c2", "f": "Biểu diễn lực bằng hình gì?", "b": "Mũi tên."}, {"id": "b41c3", "img": "", "svg": "b41c3", "f": "Gốc mũi tên cho biết gì?", "b": "Điểm đặt của lực."}, {"id": "b41c4", "img": "", "svg": "b41c4x", "f": "Độ dài mũi tên cho biết gì?", "b": "Độ lớn của lực theo tỉ lệ xích."}, {"id": "b41c5", "img": "", "svg": "b41c5x", "f": "Tỉ lệ xích dùng để làm gì?", "b": "Quy đổi độ dài mũi tên ra độ lớn của lực, ví dụ 1 cm ứng với 5 N."}],
"bai42": [{"id": "b42c1", "img": "", "svg": "b42c1x", "f": "Lò xo chịu lực thì thế nào?", "b": "Biến dạng: dãn ra hoặc nén lại."}, {"id": "b42c2", "img": "", "svg": "b42c2x", "f": "Biến dạng đàn hồi là gì?", "b": "Thôi lực, vật trở lại hình dạng ban đầu."}, {"id": "b42c3", "img": "", "svg": "b42c3x", "f": "Độ dãn của lò xo tỉ lệ với gì?", "b": "Tỉ lệ với lực kéo trong giới hạn đàn hồi."}, {"id": "b42c4", "img": "", "svg": "b42c4", "f": "Vượt quá giới hạn đàn hồi thì sao?", "b": "Lò xo không trở lại hình dạng cũ được nữa."}, {"id": "b42c5", "img": "", "svg": "b42c5x", "f": "Lực kế dùng để đo gì?", "b": "Đo độ lớn của lực, đơn vị niutơn."}],
"bai43": [{"id": "b43c1", "img": "", "svg": "b43c1", "f": "Lực hấp dẫn là gì?", "b": "Lực hút giữa mọi vật có khối lượng."}, {"id": "b43c2", "img": "", "svg": "b43c2", "f": "Trọng lượng là gì?", "b": "Độ lớn lực hút của Trái Đất tác dụng lên vật."}, {"id": "b43c3", "img": "", "svg": "b43c3x", "f": "Khối lượng khác trọng lượng thế nào?", "b": "Khối lượng không đổi mọi nơi; trọng lượng thay đổi theo nơi."}, {"id": "b43c4", "img": "", "svg": "b43c4x", "f": "Công thức tính trọng lượng gần đúng?", "b": "P = 10 × m (m bằng kg, P bằng N)."}, {"id": "b43c5", "img": "", "svg": "b43c5x", "f": "Vật 5 kg có trọng lượng khoảng bao nhiêu?", "b": "50 N."}],
"bai44": [{"id": "b44c1", "img": "", "svg": "b44c1", "f": "Lực ma sát là gì?", "b": "Lực cản khi hai vật tiếp xúc và chuyển động tương đối."}, {"id": "b44c2", "img": "", "svg": "b44c2", "f": "Ma sát trượt là gì?", "b": "Ma sát khi vật trượt trên mặt vật khác."}, {"id": "b44c3", "img": "", "svg": "b44c3", "f": "Ma sát lăn lớn hay nhỏ hơn ma sát trượt?", "b": "Nhỏ hơn."}, {"id": "b44c4", "img": "", "svg": "b44c4x", "f": "Kể 1 lợi ích của ma sát.", "b": "Đi lại không trượt ngã, phanh xe dừng được."}, {"id": "b44c5", "img": "", "svg": "b44c5", "f": "Làm sao để giảm ma sát?", "b": "Tra dầu bôi trơn, dùng ổ bi, làm mặt nhẵn."}],
"bai45": [{"id": "b45c1", "img": "", "svg": "b45c1", "f": "Lực cản của nước là gì?", "b": "Lực nước cản vật chuyển động trong nước."}, {"id": "b45c2", "img": "", "svg": "b45c2x", "f": "Vật càng nhanh thì lực cản càng thế nào?", "b": "Càng lớn."}, {"id": "b45c3", "img": "", "svg": "b45c3x", "f": "Hình dạng nào giảm lực cản của nước?", "b": "Hình thuôn dài như cá, tàu ngầm."}, {"id": "b45c4", "img": "", "svg": "b45c4x", "f": "Vì sao cá bơi nhanh?", "b": "Thân thuôn, da trơn làm giảm lực cản."}, {"id": "b45c5", "img": "", "svg": "b45c5", "f": "Lực cản của nước lớn hơn không khí không?", "b": "Lớn hơn nhiều."}],
"bai46": [{"id": "b46c1", "img": "", "svg": "b46c1x", "f": "Năng lượng là gì?", "b": "Khả năng thực hiện công: làm vật chuyển động, nóng lên, phát sáng."}, {"id": "b46c2", "img": "", "svg": "b46c2x", "f": "Đơn vị đo năng lượng là gì?", "b": "Jun (J)."}, {"id": "b46c3", "img": "", "svg": "b46c3", "f": "Năng lượng truyền bằng cách nào?", "b": "Qua đun nóng, chiếu sáng, va chạm, dòng điện."}, {"id": "b46c4", "img": "", "svg": "b46c4x", "f": "Năng lượng có tự mất đi không?", "b": "Không, chỉ chuyển dạng hoặc truyền đi."}, {"id": "b46c5", "img": "", "svg": "b46c5", "f": "Mặt Trời truyền năng lượng bằng gì?", "b": "Bằng ánh sáng qua không gian."}],
"bai47": [{"id": "b47c1", "img": "", "svg": "b47c1", "f": "Động năng là gì?", "b": "Năng lượng do vật chuyển động mà có."}, {"id": "b47c2", "img": "", "svg": "b47c2", "f": "Thế năng là gì?", "b": "Năng lượng do vị trí của vật mà có."}, {"id": "b47c3", "img": "", "svg": "b47c3", "f": "Hóa năng chứa ở đâu?", "b": "Trong thức ăn, pin, xăng dầu, chất đốt."}, {"id": "b47c4", "img": "", "svg": "b47c4", "f": "Quang năng là gì?", "b": "Năng lượng của ánh sáng."}, {"id": "b47c5", "img": "", "svg": "b47c5", "f": "Điện năng là gì?", "b": "Năng lượng của dòng điện."}],
"bai48": [{"id": "b48c1", "img": "", "svg": "b48c1x", "f": "Chuyển hóa năng lượng là gì?", "b": "Năng lượng chuyển từ dạng này sang dạng khác."}, {"id": "b48c2", "img": "", "svg": "b48c2", "f": "Đèn pin chuyển hóa năng lượng thế nào?", "b": "Hóa năng thành điện năng rồi thành quang năng."}, {"id": "b48c3", "img": "", "svg": "b48c3", "f": "Xe đạp xuống dốc chuyển hóa thế nào?", "b": "Thế năng thành động năng."}, {"id": "b48c4", "img": "", "svg": "b48c4", "f": "Quang hợp chuyển hóa thế nào?", "b": "Quang năng thành hóa năng trong lá."}, {"id": "b48c5", "img": "", "svg": "b48c5x", "f": "Chuyển hóa có làm mất năng lượng không?", "b": "Không, tổng năng lượng không đổi, chỉ đổi dạng."}],
"bai49": [{"id": "b49c1", "img": "", "svg": "b49c1", "f": "Năng lượng hao phí là gì?", "b": "Năng lượng chuyển thành dạng không có ích khi sử dụng."}, {"id": "b49c2", "img": "", "svg": "b49c2x", "f": "Động cơ xe hao phí ở đâu?", "b": "Một phần thành nhiệt năng làm nóng máy."}, {"id": "b49c3", "img": "", "svg": "b49c3", "f": "Bóng đèn dây tóc hao phí thế nào?", "b": "Phần lớn điện năng thành nhiệt, ít thành ánh sáng."}, {"id": "b49c4", "img": "", "svg": "b49c4x", "f": "Giảm hao phí bằng cách nào?", "b": "Bôi trơn, cách nhiệt, dùng thiết bị hiệu suất cao."}, {"id": "b49c5", "img": "", "svg": "b49c5", "f": "Đèn LED tiết kiệm vì sao?", "b": "Hầu hết điện năng thành ánh sáng, ít thành nhiệt."}],
"bai50": [{"id": "b50c1", "img": "", "svg": "b50c1x", "f": "Năng lượng tái tạo là gì?", "b": "Năng lượng từ nguồn tự nhiên bổ sung liên tục, không cạn kiệt."}, {"id": "b50c2", "img": "", "svg": "b50c2", "f": "Kể 3 nguồn năng lượng tái tạo.", "b": "Gió, ánh sáng Mặt Trời, nước chảy (hoặc địa nhiệt, sinh khối)."}, {"id": "b50c3", "img": "", "svg": "b50c3x", "f": "Pin mặt trời làm gì?", "b": "Biến quang năng thành điện năng."}, {"id": "b50c4", "img": "", "svg": "b50c4x", "f": "Ưu điểm của năng lượng tái tạo?", "b": "Không cạn kiệt, ít ô nhiễm."}, {"id": "b50c5", "img": "", "svg": "b50c5", "f": "Hạn chế của năng lượng tái tạo?", "b": "Phụ thuộc thời tiết, chi phí đầu tư ban đầu cao."}],
"bai51": [{"id": "b51c1", "img": "../hinh-anh/khtn/fc-bai51-tiet-kiem.webp", "svg": "", "f": "Tiết kiệm năng lượng là gì?", "b": "Dùng ít năng lượng hơn mà vẫn đủ nhu cầu."}, {"id": "b51c2", "img": "../hinh-anh/khtn/fc-bai51-tat-den.webp", "svg": "", "f": "Ở nhà tiết kiệm điện bằng cách nào?", "b": "Tắt đèn, quạt khi ra khỏi phòng, dùng đèn LED."}, {"id": "b51c3", "img": "../hinh-anh/khtn/fc-bai51-di-bo-xe-dap.webp", "svg": "", "f": "Đi quãng ngắn nên đi bằng gì?", "b": "Đi bộ hoặc xe đạp thay cho xe máy."}, {"id": "b51c4", "img": "../hinh-anh/khtn/fc-bai51-den-led.webp", "svg": "", "f": "Đèn LED tiết kiệm hơn vì sao?", "b": "Sáng như đèn thường mà tốn ít điện hơn."}, {"id": "b51c5", "img": "", "svg": "bai51xanh", "f": "Tiết kiệm năng lượng để làm gì?", "b": "Giảm chi phí, giảm ô nhiễm, giữ nguồn cho tương lai."}],
"bai52": [{"id": "b52c1", "img": "", "svg": "b52c1x", "f": "Mặt Trời mọc hướng nào, lặn hướng nào?", "b": "Mọc ở đông, lặn ở tây."}, {"id": "b52c2", "img": "../hinh-anh/khtn/fc-bai52-ngay-dem.webp", "svg": "", "f": "Vì sao có ngày và đêm?", "b": "Vì Trái Đất tự quay quanh trục từ tây sang đông."}, {"id": "b52c3", "img": "", "svg": "b52c3x", "f": "Trái Đất tự quay một vòng mất bao lâu?", "b": "Một ngày, khoảng 24 giờ."}, {"id": "b52c4", "img": "../hinh-anh/khtn/fc-bai52-thien-the.webp", "svg": "", "f": "Thiên thể là gì?", "b": "Sao, hành tinh, vệ tinh, sao chổi trên bầu trời."}, {"id": "b52c5", "img": "", "svg": "bai52matTroi", "f": "Mặt Trời là sao hay hành tinh?", "b": "Là sao, ngôi sao gần Trái Đất nhất."}],
"bai53": [{"id": "b53c1", "img": "", "svg": "b53c1", "f": "Mặt Trăng là gì của Trái Đất?", "b": "Vệ tinh tự nhiên duy nhất."}, {"id": "b53c2", "img": "", "svg": "b53c2x", "f": "Mặt Trăng quay quanh Trái Đất mất bao lâu?", "b": "Khoảng 27,3 ngày."}, {"id": "b53c3", "img": "", "svg": "b53c3", "f": "Mặt Trăng có tự phát sáng không?", "b": "Không, Mặt Trăng phản chiếu ánh sáng Mặt Trời."}, {"id": "b53c4", "img": "", "svg": "b53c4", "f": "Trăng tròn là khi nào?", "b": "Khi ta thấy toàn bộ mặt sáng của Mặt Trăng (ngày rằm)."}, {"id": "b53c5", "img": "", "svg": "b53c5", "f": "Nguyệt thực là gì?", "b": "Trái Đất che ánh sáng Mặt Trời tới Mặt Trăng."}],
"bai54": [{"id": "b54c1", "img": "", "svg": "b54c1", "f": "Hệ Mặt Trời gồm những gì?", "b": "Mặt Trời và các thiên thể quay quanh nó."}, {"id": "b54c2", "img": "", "svg": "b54c2x", "f": "Kể tên 8 hành tinh.", "b": "Thủy, Kim, Trái Đất, Hỏa, Mộc, Thổ, Thiên Vương, Hải Vương."}, {"id": "b54c3", "img": "", "svg": "b54c3", "f": "Hành tinh vòng trong khác vòng ngoài thế nào?", "b": "Vòng trong nhỏ, bằng đá; vòng ngoài lớn, bằng khí."}, {"id": "b54c4", "img": "", "svg": "b54c4", "f": "Hành tinh nào đã biết có sự sống?", "b": "Trái Đất."}, {"id": "b54c5", "img": "", "svg": "b54c5", "f": "Sao Thổ nổi bật vì gì?", "b": "Có vành đai lớn bao quanh."}],
"bai55": [{"id": "b55c1", "img": "", "svg": "b55c1", "f": "Ngân Hà là gì?", "b": "Thiên hà chứa Hệ Mặt Trời, gồm hàng trăm tỉ ngôi sao."}, {"id": "b55c2", "img": "", "svg": "b55c2", "f": "Ngân Hà có hình gì?", "b": "Hình xoắn ốc."}, {"id": "b55c3", "img": "", "svg": "b55c3", "f": "Hệ Mặt Trời nằm ở đâu trong Ngân Hà?", "b": "Ở rìa một nhánh xoắn, cách trung tâm rất xa."}, {"id": "b55c4", "img": "", "svg": "b55c4", "f": "Năm ánh sáng là gì?", "b": "Quãng đường ánh sáng đi trong một năm, đơn vị đo khoảng cách vũ trụ."}, {"id": "b55c5", "img": "", "svg": "b55c5", "f": "Ngoài Ngân Hà còn có gì?", "b": "Vô số thiên hà khác."}]
};
