b41c4x:"<svg viewBox=\"0 0 300 120\" style=\"width:100%;max-width:400px;height:auto;display:block;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"14\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1565c0\" font-family=\"Arial,sans-serif\">Độ dài mũi tên cho biết độ lớn của lực</text><line x1=\"40\" y1=\"45\" x2=\"90\" y2=\"45\" stroke=\"#fb8c00\" stroke-width=\"5\"/><polygon points=\"90,45 76,37 76,53\" fill=\"#fb8c00\"/><text x=\"65\" y=\"66\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#e65100\" font-family=\"Arial,sans-serif\">1 cm = 5 N</text><line x1=\"40\" y1=\"90\" x2=\"140\" y2=\"90\" stroke=\"#fb8c00\" stroke-width=\"5\"/><polygon points=\"140,90 126,82 126,98\" fill=\"#fb8c00\"/><text x=\"90\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#e65100\" font-family=\"Arial,sans-serif\">2 cm = 10 N</text><text x=\"215\" y=\"66\" font-size=\"11\" fill=\"#333\" font-family=\"Arial,sans-serif\">Mũi tên càng dài,</text><text x=\"215\" y=\"84\" font-size=\"11\" fill=\"#333\" font-family=\"Arial,sans-serif\">lực càng lớn.</text></svg>",
b41c5x:"<svg viewBox=\"0 0 300 120\" style=\"width:100%;max-width:400px;height:auto;display:block;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"14\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1565c0\" font-family=\"Arial,sans-serif\">Tỉ lệ xích: đổi độ dài ra độ lớn lực</text><line x1=\"50\" y1=\"60\" x2=\"170\" y2=\"60\" stroke=\"#fb8c00\" stroke-width=\"5\"/><polygon points=\"170,60 154,51 154,69\" fill=\"#fb8c00\"/><g stroke=\"#333\" stroke-width=\"1.5\"><line x1=\"50\" y1=\"60\" x2=\"50\" y2=\"70\"/><line x1=\"110\" y1=\"60\" x2=\"110\" y2=\"70\"/><line x1=\"170\" y1=\"60\" x2=\"170\" y2=\"70\"/></g><text x=\"50\" y=\"84\" text-anchor=\"middle\" font-size=\"11\" fill=\"#333\" font-family=\"Arial,sans-serif\">0</text><text x=\"110\" y=\"84\" text-anchor=\"middle\" font-size=\"11\" fill=\"#333\" font-family=\"Arial,sans-serif\">1 cm</text><text x=\"170\" y=\"84\" text-anchor=\"middle\" font-size=\"11\" fill=\"#333\" font-family=\"Arial,sans-serif\">2 cm</text><text x=\"150\" y=\"104\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1565c0\" font-family=\"Arial,sans-serif\">1 cm = 5 N → mũi tên 2 cm là 10 N</text></svg>",
